171	namespace TutorFlow.Core.Asistente;
172	
173	internal sealed partial class CitasDeReglasAplicadas
174	{
175	    private const int MaximoDeCitas = 3;
176	    private const string Reglamento = ReglasAplicadas.DocumentoReglamento;
177	
178	    private static readonly Cita Definitiva = new(ReglasAplicadas.DocumentoEvaluacion, Textos.SeccionDefinitiva);
179	    private static readonly Cita Promedio = new(ReglasAplicadas.DocumentoEvaluacion, Textos.SeccionPromedio);
180	
181	    private static readonly Dictionary<Cita, string[]> Terminos = new()
182	    {
183	        [Definitiva] = ["definitiva", "definitivas"],
184	        [Promedio] = ["promedio", "promedios"],
185	        [new Cita(Reglamento, Textos.SeccionPerdidaPorInasistencia)] = [.. FormasDePerdida.Inasistencias, "faltas", "faltar", "faltaste", "faltado"],
186	        [new Cita(ReglasAplicadas.DocumentoBienestar, Textos.SeccionBecaPorRendimiento)] = ["beca", "becas"],
187	        [new Cita(Reglamento, Textos.SeccionNotaMinima)] =
188	        [
189	            "aprobada", "aprobadas", "aprobado", "aprobados", "aprobar", "aprueba", "apruebas", "aprobo", "aprobaste", "perdida", "perdidas",
190	            "perdido", "perdidos", "perdio", "perdiste", "perdieron", "reprobada", "reprobadas", "reprobo", "reprobaron"
191	        ],
192	        [new Cita(Reglamento, Textos.SeccionHabilitacion)] = ["habilitacion", "habilitar", "habilitas", "habilitable", "habilitables", "habilitarla", "habilitarlas"],
193	        [new Cita(Reglamento, Textos.SeccionNoHabilitables)] =
194	        [
195	            "no habilitable", "no habilitables", "no es habilitable", "no son habilitables",
196	            "no puedes habilitar", "no puedes habilitarla", "no se puede habilitar"
197	        ],
198	        [new Cita(Reglamento, Textos.SeccionPruebaAcademica)] = ["prueba academica"],
199	        [new Cita(Reglamento, Textos.SeccionAsistenciaSinRegistro)] = ["sin registro", "revision"]
200	    };
201	
202	    private readonly IBaseConocimiento _baseConocimiento;
203	    private readonly DefinitivaPorAsignatura _definitivas;
204	    private readonly PerdidaPorValor _perdida;
205	
206	    public CitasDeReglasAplicadas(IBaseConocimiento baseConocimiento, DefinitivaPorAsignatura definitivas)
207	    {
208	        _baseConocimiento = baseConocimiento;
209	        _definitivas = definitivas;
210	        _perdida = new PerdidaPorValor(definitivas);
211	    }
212	
213	    public IReadOnlyList<Cita> Usadas(RegistroConsultas registro, string respuesta, DirectorioAcademico directorio)
214	    {
215	        var texto = $" {NormalizadorTexto.Normalizar(respuesta)} ";
216	        return [.. registro.Reglas.Where(regla => UsaElCampo(regla, texto, respuesta, registro, directorio))];
217	    }
218	
219	    public IReadOnlyList<Cita> De(IReadOnlyList<Cita> usadas, string pregunta, IReadOnlyCollection<Cita> escritas) =>
220	        [.. Ordenar(usadas, RaicesDeContenido.De(pregunta).ToList()).Take(MaximoDeCitas).Where(regla => !escritas.Contains(regla))];
221	
222	    private List<Cita> Ordenar(IReadOnlyList<Cita> reglas, List<string> raices) =>
223	        raices.Count == 0 ? [.. reglas] : [.. reglas.OrderByDescending(regla => Relevancia(regla, raices))];
224	
225	    private int Relevancia(Cita regla, List<string> raices)
226	    {
227	        var seccion = _baseConocimiento.ObtenerSeccion(regla);
228	        var delaSeccion = seccion is null ? [] : RaicesDeContenido.De($"{seccion.Titulo} {seccion.Texto}").ToHashSet(StringComparer.Ordinal);
229	        return raices.Count(delaSeccion.Contains);
230	    }
231	
232	    private bool UsaElCampo(Cita regla, string texto, string respuesta, RegistroConsultas registro, DirectorioAcademico directorio) =>
233	        UsaUnTermino(regla, texto, respuesta, directorio) || UsaElValor(regla, respuesta, registro, directorio);
234	
235	    private bool UsaUnTermino(Cita regla, string texto, string respuesta, DirectorioAcademico directorio) =>
236	        EscribeUnTermino(regla, texto) && (regla != Definitiva || _definitivas.SinCifrasNiAsignaturas(respuesta, directorio));
237	
238	    private static bool EscribeUnTermino(Cita regla, string texto) =>
239	        Terminos.TryGetValue(regla, out var palabras) && palabras.Any(palabra => texto.Contains($" {palabra} ", StringComparison.Ordinal));
240	
241	    private bool UsaElValor(Cita regla, string respuesta, RegistroConsultas registro, DirectorioAcademico directorio) =>
242	        (regla == Definitiva && ParPorValor(respuesta, registro, directorio))
243	        || (regla == Promedio && PromedioPorValor(respuesta, registro))
244	        || _perdida.Usa(regla, respuesta, registro, directorio);
245	
246	    private bool ParPorValor(string respuesta, RegistroConsultas registro, DirectorioAcademico directorio) =>
247	        registro.ReglasIncluyenNotas
248	        && _definitivas.ParesDe(respuesta, directorio).Any(par => registro.Resumenes.Values.Any(resumen => TieneDefinitiva(resumen, par)));
249	
250	    private static bool TieneDefinitiva(ResumenEstudiante resumen, (string Clave, string Cifra) par) =>
251	        resumen.Asignaturas.Any(resultado =>
252	            AmbitoPersonal.Clave(resultado.Asignatura.Codigo) == par.Clave
253	            && DefinitivaDe(resultado) == decimal.Parse(par.Cifra, CultureInfo.InvariantCulture));
254	
255	    private static decimal? DefinitivaDe(ResultadoAsignatura resultado) =>
256	        resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia ? 0m : resultado.Definitiva;
257	
258	    private static bool PromedioPorValor(string respuesta, RegistroConsultas registro)
259	    {
260	        var promedios = registro.Resumenes.Values.Where(resumen => resumen.Promedio is not null)
261	            .Select(resumen => resumen.Promedio!.Value.ToString("0.00", CultureInfo.InvariantCulture))
262	            .ToHashSet(StringComparer.Ordinal);
263	        return CifraConDosDecimales().Matches(TokenizadorTexto.Plegado(respuesta)).Any(cifra => promedios.Contains(cifra.Value));
264	    }
265	
266	    [GeneratedRegex(@"(?<![\d.])\d\.\d{2}(?!\d)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
267	    private static partial Regex CifraConDosDecimales();
268	}
