250	    private static bool TieneDefinitiva(ResumenEstudiante resumen, (string Clave, string Cifra) par) =>
251	        resumen.Asignaturas.Any(resultado =>
252	            AmbitoPersonal.Clave(resultado.Asignatura.Codigo) == par.Clave
253	            && DefinitivaDe(resultado) == decimal.Parse(par.Cifra, CultureInfo.InvariantCulture));
