275	internal static class CamposLigados
276	{
277	    private const string Promedio = "promedio";
278	    private const int DecimalesDelPromedio = 2;
279	    private const string MotivoDeVoz = "escribe los datos del estudiante en tercera persona, con su nombre";
280	
281	    public static string? Motivo(IReadOnlyList<BloqueDeTexto> bloques, ContextoDeAfirmaciones contexto) =>
282	        bloques.Select(bloque => MotivoDelBloque(bloque, contexto)).FirstOrDefault(motivo => motivo is not null);
283	
284	    private static string? MotivoDelBloque(BloqueDeTexto bloque, ContextoDeAfirmaciones contexto)
285	    {
286	        var personas = contexto.PersonasDe(bloque);
287	        var tokens = TokenizadorTexto.TokenizarConCifras(bloque.Texto);
288	        return personas.Tramos.Select(tramo => MotivoDelTramo(bloque, tokens, tramo, contexto)).FirstOrDefault(motivo => motivo is not null)
289	            ?? (VozEquivocada(tokens, personas, contexto.Usuario) ? MotivoDeVoz : null);
290	    }
291	
292	    private static string? MotivoDelTramo(BloqueDeTexto bloque, IReadOnlyList<TokenTexto> tokens, TramoDePersona tramo, ContextoDeAfirmaciones contexto)
293	    {
294	        if (!contexto.Resumenes.TryGetValue(tramo.PersonaId, out var resumen))
295	        {
296	            return null;
297	        }
298	
299	        var inicios = tramo.Tokens.Select(token => token.Inicio).ToHashSet();
300	        var delTramo = tokens.Where(token => inicios.Contains(token.Inicio)).ToList();
301	        var cifra = PromedioQueNoCuadra(delTramo, resumen) ?? EnteroQueNoCuadra(bloque.Texto, delTramo, resumen);
302	        return cifra is null ? null : $"el valor {cifra} no coincide con los datos entregados";
303	    }
304	
305	    private static string? PromedioQueNoCuadra(List<TokenTexto> tokens, ResumenEstudiante resumen) =>
306	        Enumerable.Range(0, tokens.Count)
307	            .Where(indice => tokens[indice].Valor == Promedio && !DefinitivaPorAsignatura.EstaNegada(tokens, indice))
308	            .Select(indice => DefinitivaPorAsignatura.CifraEfectiva(tokens, indice))
309	            .OfType<int>()
310	            .Select(posicion => tokens[posicion].Valor)
311	            .FirstOrDefault(cifra => !IgualAlPromedio(cifra, resumen.Promedio));
312	
313	    private static bool IgualAlPromedio(string cifra, decimal? promedio) =>
314	        promedio is { } valor && decimal.Parse(cifra, CultureInfo.InvariantCulture) == CalculosAcademicos.Redondear(valor, DecimalesDelPromedio);
315	
316	    private static string? EnteroQueNoCuadra(string texto, List<TokenTexto> tokens, ResumenEstudiante resumen)
317	    {
318	        var permitidos = EnterosDeAsistencia.De(resumen);
319	        return EnterosDeAsistencia.Candidatos(texto, tokens).FirstOrDefault(entero => !permitidos.Contains(entero));
320	    }
321	
322	    private static bool VozEquivocada(IReadOnlyList<TokenTexto> tokens, PersonasDeBloque personas, Usuario usuario) =>
323	        usuario.Rol == Rol.Coordinador && personas is { Ambiguo: false, Tramos.Count: 0 } && VozDeTu.Hay(tokens);
324	}

