    23	    public IReadOnlyList<Cita> EscritasConApoyo(
    24	        string texto,
    25	        IReadOnlyList<SeccionDocumento> entregadas,
    26	        IReadOnlyCollection<Cita> bloqueDeReglas,
    27	        IReadOnlyCollection<Cita> reglasConCampoUsado)
    28	    {
    29	        var apoyadas = SeccionesConApoyo(texto, entregadas).Select(apoyada => CitaDe(apoyada.Seccion)).ToHashSet();
