    33	    public IReadOnlyList<Cita> Respaldo(string texto, IReadOnlyList<SeccionDocumento> entregadas) =>
    34	        [.. SeccionesConApoyo(texto, entregadas).OrderByDescending(apoyada => apoyada.Raices).Take(1).Select(apoyada => CitaDe(apoyada.Seccion))];
    35	
    36	    public IReadOnlyList<Cita> PorTema(string texto, IReadOnlyList<SeccionDocumento> entregadas)
    37	    {
    38	        var conApoyo = SeccionesConApoyo(texto, entregadas).Select(apoyada => CitaDe(apoyada.Seccion)).ToHashSet();
    39	        var plegado = EspacioAntesDelPorcentaje().Replace(TokenizadorTexto.Plegado(texto), "%");
    40	        return [.. Temas.Where(tema => conApoyo.Contains(tema.Cita) && tema.Terminos.Any(termino => UsaElTermino(plegado, termino))).Select(tema => tema.Cita)];
    41	    }
