    43	    private static bool UsaElTermino(string plegado, string termino) =>
    44	        Regex.IsMatch(plegado, $@"(?<![\p{{L}}\p{{N}}.]){Regex.Escape(termino)}(?![\p{{L}}\p{{N}}])", RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos));
