     8	{
     9	    private static readonly HashSet<string> Terminos = new(StringComparer.Ordinal)
    10	    {
    11	        "falta", "faltas", "inasistencia", "inasistencias", "asistencia"
    12	    };
    13	
    14	    private readonly PoliticaAcceso _politicaAcceso;
    15	    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;
    16	
    17	    public DesgloseDeFaltas(PoliticaAcceso politicaAcceso, IReadOnlyList<AsignaturaCatalogo> catalogo)
    18	    {
    19	        _politicaAcceso = politicaAcceso;
    20	        _catalogo = catalogo;
    21	    }
    22	
    23	    public async Task<string?> PrepararAsync(SesionPregunta sesion, ContextoUsuario contexto, CancellationToken cancellationToken)
    24	    {
    25	        var palabras = TokenizadorTexto.Valores(sesion.Entrada.Pregunta);
    26	        var personaId = palabras.Any(Terminos.Contains) ? PersonaDelDesglose(sesion, contexto, palabras) : null;
    27	        if (personaId is null)
    28	        {
    29	            return null;
    30	        }
    31	
    32	        var resumen = await ResumenDeAsync(sesion, contexto, personaId, cancellationToken);
    33	        var claves = CatalogoAsignaturas.CodigosNombrados(sesion.Entrada.Pregunta, CatalogoAsignaturas.Vigente(_catalogo, sesion.Directorio), sesion.Directorio.CodigosAsignatura);
    34	        return resumen is null ? null : TextoDelDesglose.De(resumen, claves, contexto.Usuario.Rol == Rol.Coordinador);
    35	    }
    36	
    37	    private string? PersonaDelDesglose(SesionPregunta sesion, ContextoUsuario contexto, IReadOnlyList<string> palabras)
    38	    {
    39	        if (contexto.Usuario.Rol == Rol.Estudiante)
    40	        {
    41	            return sesion.Activacion.Entrega ? contexto.Usuario.Id : null;
    42	        }
    43	
    44	        var programas = _politicaAcceso.ProgramasAutorizados(contexto.Usuario, contexto.Directorio);
    45	        var mencionados = ActivadorPrelectura.EstudiantesMencionadosDeSusProgramas(contexto, palabras, programas);
    46	        return mencionados.Count == 1 ? mencionados[0] : null;
    47	    }
    48	
    49	    private async Task<ResumenEstudiante?> ResumenDeAsync(SesionPregunta sesion, ContextoUsuario contexto, string personaId, CancellationToken cancellationToken)
    50	    {
    51	        if (sesion.Registro.Resumenes.TryGetValue(personaId, out var leido))
    52	        {
    53	            return leido;
    54	        }
    55	
    56	        if (!_politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, personaId, contexto.Directorio).Permitido)
    57	        {
    58	            return null;
    59	        }
